"""Quarantine invalid source graphs; preserve graph and input provenance, no repair."""
import json,hashlib,html
from pathlib import Path
from .audit_baseline import validate_graph,PREPARED

def main():
 out=Path('/home/jmal/Dataset/geoquery-lsfb-graph-feasibility-v1');out.mkdir(exist_ok=False);manifest={'language':'LSFB','input_provenance':'DeepL machine translated French','target_provenance':'original author transcription of human signing; no local approval','label_type':'multilinear graph with HamNoSys; not flat gloss','synthetic_augmentation_used':False,'source_commit':'879731568a5cd93177d11bf742740b187176c99a','license':'GPL-2.0 per original release','counts':{},'files':{},'no_automatic_repairs':True};quarantine=[];review=[]
 for split in ['train','val']:
  rows=[]
  for r in map(json.loads,(PREPARED/f'human_{split}.jsonl').read_text().splitlines()):
   record={**r,'split':split,'input_provenance':'DeepL machine translated French','target_provenance':'original human signing transcription','local_linguistic_review':'pending'}
   try:validate_graph(record['lsfb_graph']);rows.append(record)
   except ValueError as e:record['quarantine_reason']=str(e);quarantine.append(record)
   review.append(record)
  p=out/f'{split}.jsonl';p.write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in rows));manifest['counts'][split]=len(rows);manifest['files'][p.name]=hashlib.sha256(p.read_bytes()).hexdigest()
 p=out/'quarantine.jsonl';p.write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in quarantine));manifest['counts']['quarantine']=len(quarantine);manifest['files'][p.name]=hashlib.sha256(p.read_bytes()).hexdigest();(out/'MANIFEST.json').write_text(json.dumps(manifest,indent=2))
 # Local review tool explicitly does not confer an approval without user action.
 payload=json.dumps(review,ensure_ascii=False).replace('</','<\\/')
 page='''<!doctype html><meta charset="utf-8"><title>GeoQuery LSFB graph review</title><style>body{font:16px system-ui;margin:2rem;background:#161b22;color:#eee}table{border-collapse:collapse}td,th{border:1px solid #555;padding:.4rem}.bad{color:#ff9292}pre{white-space:pre-wrap}button,select{font:inherit;margin:.3rem}</style><h1>GeoQuery LSFB source graph review</h1><p>French input: DeepL translation. LSFB target: author transcription. All local reviews pending. Graph order does not establish timing or natural signing.</p><select id="records"></select><h2 id="title"></h2><p id="french"></p><p id="status"></p><table><thead><tr><th>Relation / hand</th><th>Occurrence / source</th><th>HamNoSys / destination</th></tr></thead><tbody id="graph"></tbody></table><h2>Review notes</h2><textarea id="notes" rows="4" cols="80" placeholder="Describe alignment or source graph issues; no automatic repair"></textarea><br><button id="save">Download review notes</button><script>const data='''+payload+''';const sel=document.querySelector('#records');for(let i=0;i<data.length;i++){const o=document.createElement('option');o.value=i;o.textContent=data[i].id+' · '+data[i].split+(data[i].quarantine_reason?' · needs structural review':'');sel.append(o);}function draw(){const r=data[+sel.value];document.querySelector('#title').textContent='Record '+r.id;document.querySelector('#french').textContent=r.french;document.querySelector('#status').textContent=r.quarantine_reason||'Structural checks passed; linguistic review pending';const ids=new Set(r.lsfb_graph.filter(t=>t[0].includes('articulation')).map(t=>t[1]));const table=document.querySelector('#graph');table.replaceChildren();for(const t of r.lsfb_graph){const tr=document.createElement('tr');if(!t[0].includes('articulation')&&(!ids.has(t[1])||!ids.has(t[2])))tr.className='bad';for(const v of t){const td=document.createElement('td');td.textContent=v;tr.append(td);}table.append(tr);}document.querySelector('#notes').value='';}sel.onchange=draw;document.querySelector('#save').onclick=()=>{const r=data[+sel.value];const b=new Blob([JSON.stringify({id:r.id,source_commit:'879731568a5cd93177d11bf742740b187176c99a',notes:document.querySelector('#notes').value,review_status:'notes_only_not_approved',reviewer_identity:null},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='geoquery-review-'+r.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};draw();</script>'''
 Path('research/private/geoquery_graph_review.html').write_text(page);print(json.dumps(manifest,indent=2))
if __name__=='__main__':main()
